<template>
  <AuthLayout :loading="processing" :showInfoPanel="false">
    <AuthCard
      :title="$t('welcome_to_docbits')"
      :subtitle="$t('set_password_description')"
      :success="success_message"
      :error="error_message"
    >
      <!-- Hidden username for autocomplete -->
      <q-input
        v-model="user_email"
        autocomplete="username"
        class="hidden"
      />

      <!-- Password -->
      <q-input
        v-model="model['password']"
        dense
        outlined
        :label="$t('password')"
        :type="show_password ? 'text' : 'password'"
        data-test="password-input"
        :error-message="model_error['password']"
        :error="model_error['password'] != ''"
        class="w-full"
        @update:model-value="validatePassword"
      >
        <template v-slot:append>
          <button
            type="button"
            class="password-toggle"
            @click="show_password = !show_password"
          >
            <Icon
              :icon="show_password ? 'mdi:eye-off-outline' : 'mdi:eye-outline'"
              class="size-5 text-muted-foreground"
            />
          </button>
        </template>
      </q-input>

      <!-- Password checklist -->
      <PasswordChecklist :password="model['password']" @update:valid="is_password_valid = $event" />

      <!-- Confirm password -->
      <q-input
        v-model="model['password_confirm']"
        dense
        outlined
        :label="$t('confirm_password')"
        :type="show_confirm_password ? 'text' : 'password'"
        data-test="confirm-password-input"
        :error-message="model_error['password_confirm']"
        :error="model_error['password_confirm'] != ''"
        class="w-full"
        @update:model-value="validatePassword"
      >
        <template v-slot:append>
          <button
            type="button"
            class="password-toggle"
            @click="show_confirm_password = !show_confirm_password"
          >
            <Icon
              :icon="show_confirm_password ? 'mdi:eye-off-outline' : 'mdi:eye-outline'"
              class="size-5 text-muted-foreground"
            />
          </button>
        </template>
      </q-input>

      <template #actions>
        <q-btn
          unelevated
          color="primary"
          text-color="white"
          :label="$t('submit_btn')"
          class="auth-submit-btn"
          @click="submitForm()"
          @keyup.enter="submitForm"
        />
      </template>
    </AuthCard>

    <template #footer>
      <a
        class="text-sm text-primary cursor-pointer hover:underline"
        @click="user_login()"
      >{{ $t('go_to_login') }}</a>
    </template>
  </AuthLayout>
</template>

<script lang="ts">
import axios from 'axios';
import { defineComponent, ref } from 'vue';
import helperMixin from 'src/mixins/helperMixin.js';
import { LocalStorage, SessionStorage } from 'quasar';
import { api, getClientAuthorization } from 'pages/APIs';
import { AuthLayout, AuthCard, PasswordChecklist } from 'src/components/Auth';
import { specialChars, passwordPattern, CONSTANTS } from 'src/constants';

export default defineComponent({
  mixins: [helperMixin],
  components: {
    AuthLayout,
    AuthCard,
    PasswordChecklist,
  },
  setup() {
    return {
      model: ref({} as { [k: string]: any }),
      model_error: ref({} as { [k: string]: any }),
      processing: ref(false),
      success_message: ref(''),
      error_message: ref(''),
      code: ref(''),
      show_password: ref(false),
      show_confirm_password: ref(false),
      user_email: ref(''),
      is_password_valid: ref(false),
    };
  },
  mounted() {
    this.setNewModel();
    this.getEmailAndCode();
  },
  methods: {
    setNewModel() {
      this.model['password'] = '';
      this.model['password_confirm'] = '';
      this.resetErrors();
    },

    resetErrors() {
      this.error_message = '';
      this.model_error['password'] = '';
      this.model_error['password_confirm'] = '';
    },

    getEmailAndCode() {
      for (const [key, value] of Object.entries(this.$route.query)) {
        if (key === 'code') this.code = String(value);
        if (key === 'email') this.user_email = String(value);
      }
    },

    user_login() {
      this.$router.push('/');
    },

    validatePassword() {
      if (this.model['password'] && !this.is_password_valid) {
        this.model_error['password'] = this.$t('password_invalid');
      } else {
        this.model_error['password'] = '';
      }
    },

    isValidPassword(password: any) {
      return passwordPattern.test(password);
    },

    async submitForm() {
      try {
        if (!this.validateRow()) return;
        this.processing = true;
        let formData = new FormData();
        formData.append('token', this.code);
        formData.append('password', this.model['password']);
        formData.append('password_confirm', this.model['password_confirm']);
        const response = await axios.post(api.reset_password, formData, {
          headers: {
            'Content-Type': 'application/x-www-form-urlencoded',
            Authorization: getClientAuthorization(),
          },
        });
        if (response.data.success === true) {
          this.success_message = this.$t('success_message');
          this.setNewModel();
          setTimeout(() => {
            this.$router.push('/');
          }, 2000);
        }
      } catch (error: any) {
        this.handleErrors(error);
      } finally {
        this.processing = false;
      }
    },

    validateRow() {
      let error = false;
      this.resetErrors();

      if (this.model['password'] === '') {
        this.model_error['password'] = this.$t('password') + ' ' + this.$t('is_required');
        error = true;
      }

      if (!error && this.model['password_confirm'] === '') {
        this.model_error['password_confirm'] =
          this.$t('confirm_password') + ' ' + this.$t('is_required');
        error = true;
      }

      if (!error && this.model['password'] && !this.isValidPassword(this.model['password'])) {
        this.model_error['password'] = this.$t('password_invalid');
        error = true;
      }

      if (!error && this.model['password'] !== this.model['password_confirm']) {
        this.model_error['password_confirm'] = this.$t('passwords_not_match');
        error = true;
      }

      return !error;
    },

    handleErrors(error: any) {
      let msg = '';

      if (error != null && typeof error == 'object' && error.hasOwnProperty('message')) {
        msg = error.message;
      }

      if (error?.response?.data?.hasOwnProperty('message')) {
        msg = error.response.data.message;
      }

      if (!msg || msg === '') return;

      this.error_message = msg;
      throw { message: msg };
    },
  },
});
</script>

<style scoped lang="scss">
.auth-submit-btn {
  width: 100%;
  height: 44px;
  font-weight: 500;
  border-radius: 0.5rem;
}

.password-toggle {
  display: flex;
  align-items: center;
  background: none;
  border: none;
  cursor: pointer;
  padding: 0.25rem;

  &:hover {
    opacity: 0.7;
  }
}

.hidden {
  display: none;
}
</style>
